// construct sparse representation of dof-dof matrix
void mj_makeDofDofSparse(int nv, int nC, int nD, int nM,
                         const int* dof_parentid, const int* dof_simplenum,
                         int* rownnz, int* rowadr, int* diag, int* colind,
                         int reduced, int upper,
                         int* remaining) {
  // no dofs, nothing to do
  if (!nv) {
    return;
  }

  // compute rownnz
  mju_zeroInt(rownnz, nv);
  for (int i = nv - 1; i >= 0; i--) {
    // init at diagonal
    int j = i;
    rownnz[i]++;

    // process below diagonal unless reduced and dof is simple
    if (!(reduced && dof_simplenum[i])) {
      while ((j = dof_parentid[j]) >= 0) {
        // both reduced and non-reduced have lower triangle
        rownnz[i]++;

        // add upper triangle if requested
        if (upper) rownnz[j]++;
      }
    }
  }

  // accumulate rowadr
  rowadr[0] = 0;
  for (int i = 1; i < nv; i++) {
    rowadr[i] = rowadr[i - 1] + rownnz[i - 1];
  }

  // populate colind
  mju_copyInt(remaining, rownnz, nv);
  for (int i = nv - 1; i >= 0; i--) {
    // init at diagonal
    remaining[i]--;
    colind[rowadr[i] + remaining[i]] = i;

    // process below diagonal unless reduced and dof is simple
    if (!(reduced && dof_simplenum[i])) {
      int j = i;
      while ((j = dof_parentid[j]) >= 0) {
        remaining[i]--;
        colind[rowadr[i] + remaining[i]] = j;

        // add upper triangle if requested
        if (upper) {
          remaining[j]--;
          colind[rowadr[j] + remaining[j]] = i;
        }
      }
    }
  }

  // check for remaining; SHOULD NOT OCCUR
  for (int i = 0; i < nv; i++) {
    if (remaining[i] != 0) {
      mjERROR("unexpected remaining");
    }
  }

  // check total nnz; SHOULD NOT OCCUR
  int expected_nnz = upper ? nD : (reduced ? nC : nM);
  if (rowadr[nv - 1] + rownnz[nv - 1] != expected_nnz) {
    mjERROR("sum of rownnz different from expected");
  }

  // find diagonal indices
  if (diag) {
    for (int i = 0; i < nv; i++) {
      int adr = rowadr[i];
      int j = 0;
      while (colind[adr + j] < i && j < rownnz[i]) {
        j++;
      }
      if (colind[adr + j] != i) {
        mjERROR("diagonal index not found");
      }
      diag[i] = j;
    }
  }
}

// recompute nM and dof_Madr given m.dof_parentid, validate
int nM_post = 0;
for (int i=0; i < nv; i++) {
  // set address of this dof
  m->dof_Madr[i] = nM_post;

  // count ancestor dofs including self
  int j = i;
  while (j >= 0) {
    nM_post++;
    j = m->dof_parentid[j];
  }
}
if (nM_post != nM) throw mjCError(0, "nM mismatch: pre %d, post %d", nullptr, nM, nM_post);

// recompute nD, validate
int nD_post = 2 * m->nM - nv;
if (nD_post != nD) throw mjCError(0, "nD mismatch: pre %d, post %d", nullptr, nD, nD_post);

// bodies_[]->subtreedofs already computed in ComputeSparseSizes

// recompute nB given {body->subtreedofs, body->dofnum, body->parent}, validate
int nB_post = 0;

std::vector<int> scratch(m->nv);
std::vector<int> count(m->nbody);
std::vector<int> M(m->nM);

// make D
mj_makeDofDofSparse(m->nv, m->nC, m->nD, m->nM, m->dof_parentid, m->dof_simplenum,
                    m->D_rownnz, m->D_rowadr, m->D_diag, m->D_colind,
                    /*reduced=*/0, /*upper=*/1, scratch.data());

// make B
mj_makeBSparse(m->nv, m->nbody, m->nB, m->body_dofnum, m->body_parentid,
              m->body_dofadr, m->B_rownnz, m->B_rowadr, m->B_colind, count.data());

// make M
mj_makeDofDofSparse(m->nv, m->nC, m->nD, m->nM, m->dof_parentid, m->dof_simplenum,
                    m->M_rownnz, m->M_rowadr, NULL, m->M_colind,
                    /*reduced=*/1, /*upper=*/0, scratch.data());

// make index mappings: mapM2D, mapD2M, mapM2M
mj_makeDofDofMaps(m->nv, m->nM, m->nC, m->nD,
                  m->dof_Madr, m->dof_simplenum, m->dof_parentid,
                  m->D_rownnz, m->D_rowadr, m->D_colind,
                  m->M_rownnz, m->M_rowadr, m->M_colind,
                  m->mapM2D, m->mapD2M, m->mapM2M, M.data(), scratch.data());

  // make B
  mj_makeBSparse(m->nv, m->nbody, m->nB, m->body_dofnum, m->body_parentid,
                m->body_dofadr, m->B_rownnz, m->B_rowadr, m->B_colind, count.data());

  // make M
  mj_makeDofDofSparse(m->nv, m->nC, m->nD, m->nM, m->dof_parentid, m->dof_simplenum,
                      m->M_rownnz, m->M_rowadr, NULL, m->M_colind,
                      /*reduced=*/1, /*upper=*/0, scratch.data());

  // make index mappings: mapM2D, mapD2M, mapM2M
  mj_makeDofDofMaps(m->nv, m->nM, m->nC, m->nD,
                    m->dof_Madr, m->dof_simplenum, m->dof_parentid,
                    m->D_rownnz, m->D_rowadr, m->D_colind,
                    m->M_rownnz, m->M_rowadr, m->M_colind,
                    m->mapM2D, m->mapD2M, m->mapM2M, M.data(), scratch.data());
}

// create data
int disableflags = m->opt.disableflags;
m->opt.disableflags |= mjDSBL_CONTACT;
int enableflags = m->opt.enableflags;
m->opt.enableflags &= ~mjENBL_SLEEP;
mj_makeRawData(&d, m);
if (!d) {

